WITH flattened AS (SELECT id, plan, currency, element FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) x AS element) SELECT id, currency, CUME_DIST() OVER (PARTITION BY currency ORDER BY element ASC NULLS LAST) AS element_cume_dist, SUM(element) OVER (PARTITION BY plan) AS plan_sum_element, CUME_DIST() OVER (ORDER BY element DESC) AS element_cume_dist_2 FROM flattened WHERE currency IN ('THB', 'EUR')
